// Конфигурация магазина, стоимости ремонта и флагов игры
export const REPAIR_COST_GOLD = 10;

export function canRepairItem(item: GameItem): boolean {
  const maxDur = Math.max(1, Number(item.maxDurability ?? getItemDefaultMaxDurability(item)));
  const curDur = Math.max(0, Math.min(maxDur, Number(item.durability ?? maxDur)));
  return curDur < maxDur && maxDur > 1;
}

